"""Create a self-contained local investigation preview from offline exports."""
import argparse,json
from pathlib import Path
p=argparse.ArgumentParser(description=__doc__);p.add_argument('run',type=Path);a=p.parse_args()
data={name:json.loads((a.run/(name+'.json')).read_text()) for name in ['manifest','networks','alerts','transactions']}
payload=json.dumps(data,allow_nan=False).replace('<','\\u003c')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Acurion | Offline model review</title>
<style>*{box-sizing:border-box}body{margin:0;background:#f5f5f5;color:#202020;font:14px system-ui,sans-serif}header,main{max-width:1440px;margin:auto;padding:28px}header{border-bottom:1px solid #ddd;display:flex;justify-content:space-between;gap:20px}h1{font-size:26px;margin:8px 0}p{color:#666;line-height:1.65}.eyebrow{font-size:11px;letter-spacing:2px;text-transform:uppercase}.notice{padding:16px 20px;border:1px solid #d0d0d0;border-radius:14px;background:white}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.stat{background:white;border:1px solid #ddd;border-radius:14px;padding:20px}.stat b{display:block;font-size:28px;margin:10px 0}.columns{display:grid;grid-template-columns:320px 1fr;gap:18px}.panel{background:white;border:1px solid #ddd;border-radius:16px;overflow:hidden;padding:20px}.list{max-height:640px;overflow:auto}button,input{font:inherit;border:1px solid #ddd;border-radius:9px;background:white;padding:10px;color:inherit}button{cursor:pointer;transition:background .18s ease,transform .18s ease,border-color .18s ease}button:hover{background:#eee;border-color:#999}button:active{transform:scale(.98)}button.active{background:#222;color:white}input{width:100%;margin:14px 0}button:focus-visible,input:focus-visible{outline:2px solid #666;outline-offset:2px}.entry{display:block;text-align:left;width:100%;margin:8px 0}.entry small{display:block;margin-top:6px;opacity:.7}.toolbar{display:flex;gap:8px;flex-wrap:wrap}svg{width:100%;height:380px;background:#fafafa;border-radius:12px;margin-top:12px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{text-align:left;padding:12px 6px;border-bottom:1px solid #eee;vertical-align:top}td{word-break:break-word}.scroll{overflow:auto;max-height:340px}h2{font-size:19px}.tags{font-size:12px;color:#666}footer{padding:24px;color:#777;font-size:12px}.tx{margin-top:22px}.muted{color:#666} @media(max-width:850px){.columns{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}header{display:block}.list{max-height:260px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}</style>
<header><div><span class="eyebrow">Acurion / Research workspace</span><h1>Model and network review</h1><span class="muted" id="subtitle"></span></div><p>Offline evidence preview<br>Experimental models</p></header><main><div class="notice">These are recommendations for investigation. A network score applies to the connected group, not to every transfer inside it. Scores are not calibrated probabilities of money laundering.</div><div class="stats" id="stats"></div><div class="columns"><section class="panel"><h2>Network candidates</h2><div class="toolbar"><button id="review" class="active">Review alerts</button><button id="all">All scored</button><button id="independent">Independent alerts</button></div><input id="search" aria-label="Find network by ID" placeholder="Find a network ID"><div class="list" id="networks"></div></section><section class="panel"><div class="eyebrow">Historical connected context</div><h2 id="title">Select a network</h2><p id="detail"></p><div class="tags" id="tags"></div><svg id="graph" role="img" aria-label="Directed transfers in selected network"></svg><p class="muted">Arrows show transfer direction. Hover over an account or edge for details. This picture does not establish a chronological money trail or prove laundering.</p><div class="scroll"><table><thead><tr><th>Transaction</th><th>Timestamp</th><th>Paid amount</th><th>Individual result</th></tr></thead><tbody id="evidence"></tbody></table></div></section></div><section class="panel tx"><h2>Individual transaction alerts</h2><p>These alerts come from XGBoost. The displayed model score and the validation-percentile decision threshold use different scales.</p><div class="scroll"><table><thead><tr><th>Transaction</th><th>Timestamp</th><th>Model score</th><th>Validation percentile</th><th>Reason</th></tr></thead><tbody id="transactions"></tbody></table></div></section><footer id="footer"></footer></main>
<script>const RUN=__PAYLOAD__;
const byId=id=>document.getElementById(id);let mode='review';
const el=(tag,text,parent)=>{const n=document.createElement(tag);if(text!==null)n.textContent=text;if(parent)parent.append(n);return n;};
const cov=RUN.manifest.coverage;byId('subtitle').textContent=RUN.manifest.datasetId+' | '+RUN.manifest.day+' | frozen checkpoints';
for(const [label,key] of [['Transactions scored','targetTransactions'],['Transaction alerts','transactionAlerts'],['Networks scored','networksScored'],['Network review alerts','networkReviewAlerts']]){const n=el('div',null,byId('stats'));n.className='stat';el('span',label,n);el('b',cov[key].toLocaleString(),n);}
function show(n){byId('title').textContent=n.networkId;byId('detail').textContent=n.reason;byId('tags').textContent='Network score '+n.score.toFixed(4)+' | threshold '+n.threshold.toFixed(4)+' | '+n.candidateOrigins.join(' + ')+' | '+n.modelVersion;
 const svg=byId('graph');svg.replaceChildren();svg.setAttribute('viewBox','0 0 800 380');const ns='http://www.w3.org/2000/svg';const s=(tag,attrs,parent)=>{const x=document.createElementNS(ns,tag);for(const[k,v]of Object.entries(attrs))x.setAttribute(k,v);(parent||svg).append(x);return x;};const defs=s('defs',{});const marker=s('marker',{id:'arrow',viewBox:'0 0 10 10',refX:12,refY:5,markerWidth:5,markerHeight:5,orient:'auto-start-reverse'},defs);s('path',{d:'M 0 0 L 10 5 L 0 10 z',fill:'#888'},marker);
 const pts=new Map(n.nodes.map((v,i)=>[v.id,{x:400+280*Math.cos(i*2*Math.PI/n.nodes.length),y:190+145*Math.sin(i*2*Math.PI/n.nodes.length)}]));
 for(const e of n.edges){const a=pts.get(e.from),b=pts.get(e.to);const line=s('line',{x1:a.x,y1:a.y,x2:b.x,y2:b.y,stroke:e.transactionId===n.seedTransactionId?'#111':'#bbb','stroke-width':e.transactionId===n.seedTransactionId?2.5:1,'marker-end':'url(#arrow)'});s('title',{},line).textContent=e.transactionId+' | '+e.timestamp+' | paid '+e.amountPaid;}
 for(const v of n.nodes){const p=pts.get(v.id);const c=s('circle',{cx:p.x,cy:p.y,r:6,fill:'#333',stroke:'white','stroke-width':2});s('title',{},c).textContent=v.id;const t=s('text',{x:p.x,y:p.y-11,'text-anchor':'middle','font-size':9,fill:'#555'});t.textContent=v.id.length>14?v.id.slice(0,14)+'…':v.id;}
 byId('evidence').replaceChildren();for(const e of n.edges){const tr=el('tr',null,byId('evidence'));const tx=RUN.transactions[e.transactionId];for(const v of [e.transactionId,e.timestamp,e.amountPaid.toLocaleString()+' '+(tx?.paymentCurrency||''),tx?.decision==='flag'?'XGBoost review alert':'Not individually flagged; network context'])el('td',v,tr);}}
function list(){const rows=RUN.networks.filter(n=>(mode==='all'||n.decision==='review')&&(mode!=='independent'||!n.candidateOrigins.includes('xgboost'))&&n.networkId.toLowerCase().includes(byId('search').value.toLowerCase()));byId('networks').replaceChildren();for(const n of rows){const b=el('button',n.networkId,byId('networks'));b.className='entry';el('small',n.edges.length+' transfers | score '+n.score.toFixed(3)+' | '+n.candidateOrigins.join(' + '),b);b.onclick=()=>show(n);}if(!rows.length)el('p','No matching candidates',byId('networks'));else show(rows[0]);}
for(const id of ['review','all','independent'])byId(id).onclick=()=>{mode=id;for(const x of ['review','all','independent'])byId(x).classList.toggle('active',x===id);list();};byId('search').oninput=list;
for(const a of Object.values(RUN.alerts)){const tr=el('tr',null,byId('transactions'));const tx=RUN.transactions[a.transactionId];for(const v of [a.transactionId,a.timestamp,a.riskScore.toFixed(5),(tx.policyRank*100).toFixed(5)+'%',a.reason])el('td',v,tr);}
byId('footer').textContent='Coverage: '+cov.structuralSeeds+' structural seeds, '+cov.unionSeeds+' combined seeds, '+cov.networksSkipped+' skipped networks. Unselected networks remain unassessed. Timezone interpretation: '+RUN.manifest.sourceTimezone+'. Generated '+RUN.manifest.evaluatedAt+'.';list();</script></html>'''
(a.run/'review.html').write_text(html.replace('__PAYLOAD__',payload));print(a.run/'review.html')
